# [doc = " Generates a `#[test]` that verifies that all referenced variables"] # [doc = " exist on this structure."] fn generate_test (slug : & syn :: Path , structure : & Structure < '_ >) -> TokenStream { for field in structure . variants () . iter () . flat_map (| v | v . ast () . fields . iter ()) { for attr_name in field . attrs . iter () . filter_map (| at | at . path () . get_ident ()) { if attr_name == "subdiagnostic" { return quote ! () ; } } } use std :: sync :: atomic :: { AtomicUsize , Ordering } ; static COUNTER : AtomicUsize = AtomicUsize :: new (0) ; let slug = slug . get_ident () . unwrap () ; let ident = quote :: format_ident ! ("verify_{slug}_{}" , COUNTER . fetch_add (1 , Ordering :: Relaxed)) ; let ref_slug = quote :: format_ident ! ("{slug}_refs") ; let struct_name = & structure . ast () . ident ; let variables : Vec < _ > = structure . variants () . iter () . flat_map (| v | v . ast () . fields . iter () . filter_map (| f | f . ident . as_ref () . map (| i | i . to_string ()))) . collect () ; quote ! { # [cfg (test)] # [test] fn # ident () { let variables = [# (# variables) ,*] ; for vref in crate :: fluent_generated ::# ref_slug { assert ! (variables . contains (vref) , "{}: variable `{vref}` not found ({})" , stringify ! (# struct_name) , stringify ! (# slug)) ; } } } }